  quantum_info->depth = depth;

  if (quantum_info->format != UndefinedQuantumFormat)
    return(MagickTrue);
  if (quantum_info->depth != 8U && quantum_info->depth != 16U)
    return(MagickTrue);

  return(MagickTrue);
}

