MagickBooleanType SetQuantumDepth(const Image *image, QuantumInfo *quantum_info, const size_t depth) {
  assert(image != (const Image *) NULL);
  assert(image->signature == MagickSignature);
  assert(quantum_info != (QuantumInfo *) NULL);
  assert(quantum_info->signature == QuantumInfoSignature);

  if (GetMagickBoolImageOption(image, "debug-quantum"))
    (void) LogMagickEvent(CoderEvent, GetMagickModule(), "Setting quantum depth for %s", image->filename);

  quantum_info->depth = depth;

  switch (quantum_info->format) {
    case UndefinedQuantumFormat:
      break;
    case AssociatedQuantumFormat:
      quantum_info->alpha_type = AssociatedQuantumAlphaType;
      break;
    case DisassociatedQuantumFormat:
      quantum_info->alpha_type = DisassociatedQuantumAlphaType;
      break;
    case NotQuantumFormat:
      break;
  }

  return MagickTrue;
}

MagickBooleanType SetQuantumDepth(const Image *image, QuantumInfo *quantum_info, const size_t depth) {
  assert(image != (const Image *) NULL);
  assert(image->signature == MagickSignature);
  assert(quantum_info != (QuantumInfo *) NULL);
  assert(quantum_info->signature == QuantumInfoSignature);

  if (debug != (char *) NULL)
    (void) LogMagickEvent(CoderEvent, GetMagickModule(), "  Setting quantum depth for \"%s\"", image->filename);

  quantum_info->depth = depth;

  if (quantum_info->quantum_format == UndefinedQuantumFormat)
    return(MagickTrue);

  return(MagickTrue);
}
